Approve the unchanged head 0a2cd38a37e132b14e626541d6dcc0dc183165f4 and request another integration assessment with the missing baseline evidence. No source, scope, policy or acceptance criterion changes.

The protected native Git-object proof and negative controls are retained at https://github.com/juangcarmona/lighthouse/tree/aab52c457375169a28127a7e24ff37d325b01c7f/acceptance/20261108-worker-completion/567/candidate-72. The payload below is a compressed representation of those same objects. Verify it locally against the host-supplied currentRevision and binding.head; this requires no Git history, network, credentials or file writes. Native Git object hashes authenticate the complete baseline and candidate file identities before the byte-prefix comparison. It proves 21,881 preserved bytes and exactly one appended test.

Run this read-only command inside the existing assessment sandbox; its assertions, not this review prose, establish the prefix result. This supplemental evidence does not establish later delivery/recovery qualification.

```bash
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import{inflateRawSync}from'node:zlib';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
function verifyPrefix(proof, candidate, expectedBase, expectedHead) {
  assert.equal(proof.base, expectedBase); assert.equal(proof.head, expectedHead);
  assert.equal(proof.path,'src/summary.test.mjs');
  const sha=(type,data)=>createHash('sha1').update(Buffer.from(type+' '+data.length+'\0')).update(data).digest('hex');
  const object=(id,type)=>{const o=proof.objects[id];assert(o,'Missing Git object '+id);assert.equal(o.type,type);assert.equal(o.encoding,'deflate-raw-base64');const data=inflateRawSync(Buffer.from(o.data,'base64'),{maxOutputLength:256000});assert.equal(sha(type,data),id,'Git object hash mismatch');return data};
  const file=(commit)=>{
    const contents=object(commit,'commit').toString('utf8');let tree=/^tree ([a-f0-9]{40})\n/.exec(contents)[1];
    for(const part of proof.path.split('/')){
      const raw=object(tree,'tree');let found=null;
      for(let offset=0;offset<raw.length;){const space=raw.indexOf(32,offset),end=raw.indexOf(0,space);assert(space>=offset&&end>space&&end+21<=raw.length);const name=raw.subarray(space+1,end).toString('utf8');const id=raw.subarray(end+1,end+21).toString('hex');if(name===part)found=id;offset=end+21}
      assert(found,'Missing Git tree entry '+part);tree=found;
    }
    return tree;
  };
  const before=object(file(proof.base),'blob');
  assert.equal(sha('blob',candidate),file(proof.head),'Workspace differs from accepted candidate');
  assert(candidate.length>before.length);assert(candidate.subarray(0,before.length).equals(before),'Original test bytes changed');
  const appended=candidate.subarray(before.length).toString('utf8');assert.equal((appended.match(/^test\(/gm)??[]).length,1,'Expected exactly one appended test');
  return {base:proof.base,head:proof.head,path:proof.path,baselineGitBlob:file(proof.base),candidateGitBlob:file(proof.head),preservedPrefixBytes:before.length,baselineSha256:createHash('sha256').update(before).digest('hex'),candidatePrefixSha256:createHash('sha256').update(candidate.subarray(0,before.length)).digest('hex'),appendedTests:1,passed:true};
}

const context=JSON.parse(readFileSync('/input/context.json','utf8'));
const completion=context.completion??context.request.completion;
const review=[...completion.pullRequest.reviews].reverse().find(r=>r.body.includes('<!-- lighthouse-prefix-proof:'));
assert(review,'Missing attached Git proof');
const proof=JSON.parse(/<!-- lighthouse-prefix-proof:(\{[^\n]*\}) -->/.exec(review.body)[1]);
console.log(JSON.stringify(verifyPrefix(proof,readFileSync('/workspace/src/summary.test.mjs'),completion.currentRevision,completion.binding.head)));
NODE
```

